    describe('When transformRedemptionFare is called', function () {
        beforeEach(inject(function () {
            localStorageService.set('bookingUrlParams', _mockRemptionBookingURLParams2);
        }));

        describe('When the booking URL have child', function () {
            beforeEach(
                inject(function () {
                    var mockRemptionBookingURLParams = mockRedemptionFareData2;
                    mockRemptionBookingURLParams.child = 2;
                    localStorageService.set('bookingUrlParams', mockRemptionBookingURLParams);
                }));
            it('the returned value have 1 child', function (done) {
                returnedValue = BookingAvailabilityTransformer.transformRedemptionFare(mockRedemptionFareData2);
                expect(returnedValue.totalPrice.price).toEqual({ 'totalCash': '172,32 €', 'totalAvios': '80,000 Avios' });
                expect(returnedValue.totalPrice.fareAviosPerPassenger).toEqual(0.5);
                expect(returnedValue.totalPrice.tax).toEqual(98.78);
                done();
            });
        });

        describe('When only have adults', function () {
            inject(function () {
                localStorageService.set('bookingUrlParams', _mockRemptionBookingURLParams2);
            });
            it('the returned value dont have any child', function (done) {
                var returnedValue = BookingAvailabilityTransformer.transformRedemptionFare(mockRedemptionFareData2);
                expect(returnedValue.totalPrice.tax).toEqual(98.78);
                expect(returnedValue.totalPrice.price).toEqual({ 'totalCash': '172,32 €', 'totalAvios': '80,000 Avios' });
                expect(returnedValue.totalPrice.fareAviosPerPassenger).toEqual(1);
                expect(returnedValue.withoutAviosMoney).toBe(true);
                done()
            });
        });

        describe('When the user cant select the fare', function () {
            it('the returned value of withoutAviosMoney is true', function (done) {
                fakeIbOriginDestinationInfoUtilsService.getSlidesData = jasmine.createSpy('getSlidesData').and.callFake(function () {
                    return mockSlidesData;
                });
                var mockRedemptionFareData = angular.copy(mockRedemptionFareData2);
                mockRedemptionFareData.offers[0].redemptionOptions = [
                    {
                        'optionId': '1',
                        'totalCash': {
                            'fare': 0.00,
                            'currency': 'EUR'
                        },
                        'totalPoints': {
                            'fare': 7500.00,
                            'currency': 'AVIOS'
                        },
                        "taxes": {
                            "price": {
                                "fare": 0,
                                "tax": 98.78,
                                "total": 98.78,
                                "currency": "EUR",
                                "ticketingFee": 0
                            },
                        },
                        'eligible': false
                    }
                ];
                returnedValue = BookingAvailabilityTransformer.transformRedemptionFare(mockRedemptionFareData);
                expect(returnedValue.totalPrice.tax).toEqual(98.78);
                expect(returnedValue.totalPrice.price).toEqual({ 'totalCash': '172,32 €', 'totalAvios': '80,000 Avios' });
                expect(returnedValue.totalPrice.fareAviosPerPassenger).toEqual(7500);
                expect(returnedValue.withoutAviosMoney).toBe(true);

                done();
            });

        });

        it('and have all data the execution is fine', function (done) {
            returnedValue = BookingAvailabilityTransformer.transformRedemptionFare(mockRedemptionFareData2);
            expect(returnedValue.totalPrice.tax).toEqual(98.78);
            expect(returnedValue.totalPrice.price).toEqual({ 'totalCash': '172,32 €', 'totalAvios': '80,000 Avios' });
            expect(returnedValue.totalPrice.fareAviosPerPassenger).toEqual(1);
            expect(returnedValue.withoutAviosMoney).toBe(true);

            done();
        });

    });


