    describe('When isFareCompatible is called', function () {
        describe('When selected offer id equals farefamily offer id', function () {
            it('should return isCompatible true', function (done) {
                var mockFarefamilyOffers = [{ 'offerId': 'AAA' }];
                var mockSelectedOffers = [{ 'offerId': 'AAA' }];
                var returnedCompatible = BookingAvailabilityTransformer.isFareCompatible(mockFarefamilyOffers, mockSelectedOffers)
                expect(returnedCompatible).toBeTruthy();
                done()
            });
        });
        describe('When selected offer id doesnt equals farefamily offer id', function () {
            it('should return isCompatible false', function (done) {
                var mockFarefamilyOffers = [{ 'offerId': 'AAA' }]
                var mockSelectedOffers = [{ 'offerId': 'BBB' }]
                var returnedCompatible = BookingAvailabilityTransformer.isFareCompatible(mockFarefamilyOffers, mockSelectedOffers)
                expect(returnedCompatible).toBeFalsy()
                done()
            });
        });
    });

